def get_url_for_query(api_url: str, user_id: str) -> str | None:
    if not user_id:
        return None
    # Ensure api_url ends with a single slash before appending user_id
    if not api_url.endswith('/'):
        api_url += '/'
    return f"{api_url}{user_id}"
